using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private readonly ShoppingCart _cart;

    public ShoppingCartTests()
    {
        _cart = new ShoppingCart();
    }

    // ── AddItem ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _cart.AddItem("SKU-1", 2, 9.99m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual((2, 9.99m), _cart.Items["SKU-1"]);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _cart.AddItem("SKU-1", 1, 5.00m);
        _cart.AddItem("SKU-1", 3, 5.00m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual(4, _cart.Items["SKU-1"].Quantity);
    }

    [TestMethod]
    public void AddItem_DifferentSkus_AddsMultipleEntries()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 2, 20m);

        Assert.HasCount(2, _cart.Items);
    }

    [TestMethod]
    public void AddItem_NullSku_ThrowsArgumentNullException()
    {
        Assert.ThrowsExactly<ArgumentNullException>(() => _cart.AddItem(null!, 1, 1m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQuantity_ThrowsArgumentOutOfRangeException(int quantity)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-1", quantity, 10m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-1", 1, -1m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Succeeds()
    {
        _cart.AddItem("FREE", 1, 0m);

        Assert.AreEqual(0m, _cart.Items["FREE"].Price);
    }

    // ── RemoveItem ───────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-1", 1, 10m);
        _cart.RemoveItem("SKU-1");

        Assert.IsEmpty(_cart.Items);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFoundException()
    {
        Assert.ThrowsExactly<KeyNotFoundException>(() => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    public void RemoveItem_NullSku_ThrowsArgumentNullException()
    {
        Assert.ThrowsExactly<ArgumentNullException>(() => _cart.RemoveItem(null!));
    }

    [TestMethod]
    public void RemoveItem_OnlyRemovesTargetSku()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 1, 20m);
        _cart.RemoveItem("A");

        Assert.HasCount(1, _cart.Items);
        Assert.Contains("B", _cart.Items.Keys);
    }

    // ── CalculateTotal ───────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsQuantityTimesPrice()
    {
        _cart.AddItem("SKU-1", 3, 10.50m);

        Assert.AreEqual(31.50m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _cart.AddItem("A", 2, 5m);   // 10
        _cart.AddItem("B", 1, 7.50m); // 7.50

        Assert.AreEqual(17.50m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemovingItem_ExcludesRemovedItem()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 1, 20m);
        _cart.RemoveItem("A");

        Assert.AreEqual(20m, _cart.CalculateTotal());
    }

    // ── ApplyCoupon ──────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 10)]
    [DataRow("SAVE20", 20)]
    [DataRow("HALF", 50)]
    public void ApplyCoupon_ValidCode_AppliesDiscount(string code, int discountPercent)
    {
        _cart.AddItem("SKU-1", 1, 100m);
        _cart.ApplyCoupon(code);

        var expected = 100m - 100m * discountPercent / 100m;
        Assert.AreEqual(expected, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_Accepted()
    {
        _cart.AddItem("SKU-1", 1, 100m);
        _cart.ApplyCoupon("save10");

        Assert.AreEqual(90m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_SetsAppliedCouponProperty()
    {
        _cart.ApplyCoupon("SAVE10");

        Assert.AreEqual("SAVE10", _cart.AppliedCoupon);
    }

    [TestMethod]
    public void ApplyCoupon_UnknownCode_ThrowsArgumentException()
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _cart.ApplyCoupon("BOGUS"));
        Assert.Contains("BOGUS", ex.Message);
    }

    [TestMethod]
    public void ApplyCoupon_NullCode_ThrowsArgumentNullException()
    {
        Assert.ThrowsExactly<ArgumentNullException>(() => _cart.ApplyCoupon(null!));
    }

    [TestMethod]
    public void ApplyCoupon_EmptyCode_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon("   "));
    }

    [TestMethod]
    public void ApplyCoupon_OnEmptyCart_TotalRemainsZero()
    {
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_ReplacesExistingCoupon()
    {
        _cart.AddItem("SKU-1", 1, 100m);
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("HALF");

        Assert.AreEqual("HALF", _cart.AppliedCoupon);
        Assert.AreEqual(50m, _cart.CalculateTotal());
    }
}

